#!/usr/bin/env node
/**
 * Flatten single-file guide subdirectories from
 *   guides/<name>/index.{md,mdx}
 * into
 *   guides/<name>.{md,mdx}
 *
 * This removes the wrapping autogenerated sidebar group that Starlight
 * creates for each subdirectory, so breadcrumbs on consolidated guide
 * pages collapse from "Guides / angular / Angular guide" to just
 * "Guides / Angular guide".
 *
 * Special cases:
 *  - guides/frameworks/laravel/index.md → guides/laravel.md (drops the
 *    "frameworks" dir entirely; adds redirect for the old URL)
 *  - guides/genai-claude-code-mcp/claude-code-mcp-guide.md →
 *    guides/genai-claude-code-mcp.md (chapter-slug URL collapses to
 *    dir-slug URL; adds redirect)
 *
 * Usage:
 *   node scripts/flatten-guide-dirs.mjs --dry-run
 *   node scripts/flatten-guide-dirs.mjs
 */
import fs from "node:fs";
import path from "node:path";

const ARGS = process.argv.slice(2);
const DRY = ARGS.includes("--dry-run");

const REPO = path.resolve(new URL("..", import.meta.url).pathname);
const GUIDES = path.join(REPO, "src/content/docs/guides");
const REDIRECTS_FILE = path.join(REPO, "src/data/redirects-migration.json");

function listEntries(dir) {
  return fs.readdirSync(dir, { withFileTypes: true });
}

function mdFiles(dir) {
  return listEntries(dir).filter((e) => e.isFile() && /\.mdx?$/.test(e.name));
}

function subdirs(dir) {
  return listEntries(dir).filter((e) => e.isDirectory());
}

/**
 * Returns { src, dst, fromUrl, toUrl } or null if the directory
 * shouldn't be flattened.
 */
function plan(dir, opts = {}) {
  const { urlBase } = opts; // e.g. "/guides/frameworks"
  const base = urlBase ?? "/guides";
  const files = mdFiles(dir);
  const subs = subdirs(dir);

  // Skip if this dir has subdirs of its own (we handle nested dirs via
  // recursion, not here).
  if (subs.length > 0) return null;
  if (files.length !== 1) return null;

  const file = files[0];
  const dirName = path.basename(dir);
  const parent = path.dirname(dir);
  const ext = file.name.match(/\.(mdx?)$/)[1];
  const dst = path.join(parent, `${dirName}.${ext}`);
  const src = path.join(dir, file.name);

  const fileSlug = file.name.replace(/\.mdx?$/, "");
  const fromUrl =
    fileSlug === "index"
      ? `${base}/${dirName}/`
      : `${base}/${dirName}/${fileSlug}/`;
  // Destination always serves at parent URL + dirName/
  const toUrl = `${path.dirname(base === "/" ? "/guides" : base).replace(/\\/g, "/")}/${dirName}/`.replace(
    /\/+/g,
    "/",
  );
  // ^ For urlBase="/guides" the parent is "/", so toUrl = "/guides/<dir>/" — but
  // path.dirname("/guides") is "/". Let's simplify:
  const toUrlClean = `${base}/${dirName}/`;
  return { src, dst, fromUrl, toUrl: toUrlClean };
}

function main() {
  const actions = [];

  // Pass 1: direct children of guides/
  for (const e of subdirs(GUIDES)) {
    const dir = path.join(GUIDES, e.name);
    const subs = subdirs(dir);

    if (subs.length === 0) {
      const p = plan(dir);
      if (p) actions.push({ ...p, dirToRemove: dir });
      continue;
    }

    // Nested: flatten the inner dir. Currently only frameworks/laravel.
    // Target: move to guides/<inner>.<ext> (flattening BOTH levels).
    for (const sub of subs) {
      const innerDir = path.join(dir, sub.name);
      const files = mdFiles(innerDir);
      const innerSubs = subdirs(innerDir);
      if (innerSubs.length > 0 || files.length !== 1) continue;

      const file = files[0];
      const ext = file.name.match(/\.(mdx?)$/)[1];
      const dst = path.join(GUIDES, `${sub.name}.${ext}`);
      const src = path.join(innerDir, file.name);
      const fileSlug = file.name.replace(/\.mdx?$/, "");
      const fromUrl =
        fileSlug === "index"
          ? `/guides/${e.name}/${sub.name}/`
          : `/guides/${e.name}/${sub.name}/${fileSlug}/`;
      const toUrl = `/guides/${sub.name}/`;
      actions.push({
        src,
        dst,
        fromUrl,
        toUrl,
        dirToRemove: innerDir,
        outerDirToRemove: dir, // remove parent dir after inner empties out
      });
    }
  }

  console.log(`Planned ${actions.length} move(s)${DRY ? " (dry run)" : ""}`);

  const redirectsToAdd = [];
  for (const a of actions) {
    const relSrc = path.relative(REPO, a.src);
    const relDst = path.relative(REPO, a.dst);
    const urlChange = a.fromUrl !== a.toUrl;
    console.log(
      `  ${relSrc}\n  → ${relDst}${urlChange ? `  [redirect ${a.fromUrl} → ${a.toUrl}]` : ""}`,
    );

    if (DRY) continue;

    if (fs.existsSync(a.dst)) {
      console.error(`    ! destination exists, skipping: ${relDst}`);
      continue;
    }

    fs.renameSync(a.src, a.dst);
    try {
      fs.rmdirSync(a.dirToRemove);
    } catch (err) {
      console.error(`    ! failed to rmdir ${a.dirToRemove}: ${err.message}`);
    }
    if (a.outerDirToRemove) {
      try {
        // Only remove if now empty.
        if (fs.readdirSync(a.outerDirToRemove).length === 0) {
          fs.rmdirSync(a.outerDirToRemove);
        }
      } catch (err) {
        console.error(
          `    ! failed to rmdir ${a.outerDirToRemove}: ${err.message}`,
        );
      }
    }

    if (urlChange) redirectsToAdd.push({ from: a.fromUrl, to: a.toUrl });
  }

  if (!DRY && redirectsToAdd.length > 0) {
    const existing = JSON.parse(fs.readFileSync(REDIRECTS_FILE, "utf8"));
    const seen = new Set(existing.map((r) => r.from));
    for (const r of redirectsToAdd) {
      if (!seen.has(r.from)) {
        existing.push(r);
        seen.add(r.from);
      }
    }
    fs.writeFileSync(
      REDIRECTS_FILE,
      JSON.stringify(existing, null, 2) + "\n",
      "utf8",
    );
    console.log(
      `\nAppended ${redirectsToAdd.length} redirect(s) to ${path.relative(REPO, REDIRECTS_FILE)}`,
    );
  }

  console.log("\nDone.");
}

main();
